isitsouthernutah.com\\/events\\/kanab-writers-conference\\/\",\"name\":\"Kanab Writers Conference | Visit Southern Utah\",\"isPartOf\":{\"@id\":\"https:\\/\\/visitsouthernutah.com\\/#website\"},\"primaryImageOfPage\":{\"@id\":\"https:\\/\\/visitsouthernutah.com\\/events\\/kanab-writers-conference\\/#primaryimage\"},\"datePublished\":\"2019-09-29T19:46:21+00:00\",\"dateModified\":\"2023-04-03T21:38:50+00:00\",\"description\":\"Visit Southern Utah Kanab Writers Conference\",\"breadcrumb\":{\"@id\":\"https:\\/\\/visitsouthernutah.com\\/events\\/kanab-writers-conference\\/#breadcrumb\"},\"inLanguage\":\"en-US\",\"potentialAction\":[{\"@type\":\"ReadAction\",\"target\":[\"https:\\/\\/visitsouthernutah.com\\/events\\/kanab-writers-conference\\/\"]}]},{\"@type\":\"BreadcrumbList\",\"@id\":\"https:\\/\\/visitsouthernutah.com\\/events\\/kanab-writers-conference\\/#breadcrumb\",\"itemListElement\":[{\"@type\":\"ListItem\",\"position\":1,\"name\":\"Home\",\"item\":\"https:\\/\\/visitsouthernutah.com\\/\"},{\"@type\":\"ListItem\",\"position\":2,\"name\":\"Events\",\"item\":\"https:\\/\\/visitsouthernutah.com\\/events\\/\"},{\"@type\":\"ListItem\",\"position\":3,\"name\":\"Kanab Writers Conference\"}]}]}},\"acf\":{\"additional_heading\":\"\",\"location_name\":\"Kanab Center\",\"address\":\"20 North 100 East Kanab, Utah 84741\",\"contact_number\":\"\",\"start_datetime\":\"November 2, 2023 1:00 pm\",\"multi_day_event\":true,\"end_date\":\"November 4, 2023 17:00:00\",\"category\":{\"term_id\":9,\"name\":\"Annual Category\",\"slug\":\"annual-category\",\"term_group\":0,\"term_taxonomy_id\":9,\"taxonomy\":\"event_categories\",\"description\":\"#FE5000\",\"parent\":0,\"count\":0,\"filter\":\"raw\"},\"redirect_url\":\"https:\\/\\/kanabwritersconference.com\\/\",\"information_block\":\"<p><img src=\\\"https:\\/\\/i1.wp.com\\/kanabwritersconference.com\\/wp-content\\/uploads\\/2018\\/04\\/banner-big-skinny-2.png?fit=1700%2C554&amp;ssl=1\\\" \\/><\\/p>\\n<p>The Kanab Writers Conference offers a plein air hike with writing retreat, a self-publishing seminar, more than twenty-five quality breakout classes taught by authors and industry professionals, a writing contest, and pitch sessions to editors.<\\/p>\\n<p><img src=\\\"https:\\/\\/www.visitsouthernutah.com\\/media\\/uploads\\/images\\/writers%20conference%202019.jpg\\\" alt=\\\"\\\" \\/><\\/p>\\n<p>The Kanab Writers Conference began in 2010 as \\u201cWriters of the Purple Sage,\\u201d a nod to Zane Grey and his use of Kane County as a setting in some of his westerns.\\u00a0 It was hosted by the Kane County Center for Education, Business, and the Arts (CEBA). In those days the conference was smaller and focused on different genres of writing, for example, historic fiction or poetry, each year.<\\/p>\\n<p>In 2013, the focus of the writers conference shifted to a broader base and targeted presentations directed more toward building individual writing skills. Under the direction of Liz Adair, the event was renamed the Kanab Writers Conference.<\\/p>\\n<p>Since that time, the conference has grown into a diverse and inspiring community with presenters and attendees from all over the country and every walk of the publishing life. Every year more and more world-class authors, publishers and editors join our faculty.\\u00a0 We look forward to your participation since every new writer brings something new and unique to our community.<\\/p>\\n\",\"information_heading\":\"\",\"information_block_1\":\"\",\"gallery\":false,\"information_block_2\":\"\",\"related_events\":\"\",\"recurrance\":\"\",\"document_download\":false},\"featured_image_url\":\"\\/wp-content\\/uploads\\/2019\\/09\\/kwc1-768x504.png\",\"_links\":{\"self\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\\/1786\"}],\"collection\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\"}],\"about\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/types\\/events\"}],\"author\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/users\\/8\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media\\/8532\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media?parent=1786\"}],\"wp:term\":[{\"taxonomy\":\"event_categories\",\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/event_categories?post=1786\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}',1,'2023-10-05 04:52:01','2023-10-06 22:56:14'),(63,'Kanab Spooktacular Trunk or Treat','vsu','1783',168,'Join us for the best Trunk or Treat Spooktacular around!\n\n\n\n\n\n\nSign up to bring your own vehicle as part of our trunks, or bring the family for fun and treats!\nTrunks can be business or personal.\nIf you are interested in signing up to participate in the Trunk or Treat please visit the link below.\n&nbsp;\nSign up here! Spaces are limited!!\n\n\n\n\n&nbsp;',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2023-10-31 17:00:00',NULL,'{\"id\":1783,\"date\":\"2019-09-29T19:43:18\",\"date_gmt\":\"2019-09-29T19:43:18\",\"guid\":{\"rendered\":\"http:\\/\\/kanecounty.fluidstaging.com\\/?post_type=events&#038;p=1783\"},\"modified\":\"2023-09-26T10:45:40\",\"modified_gmt\":\"2023-09-26T16:45:40\",\"slug\":\"kanab-spooktacular\",\"status\":\"publish\",\"type\":\"events\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/kanab-spooktacular\\/\",\"title\":{\"rendered\":\"Kanab Spooktacular Trunk or Treat\"},\"content\":{\"rendered\":\"\",\"protected\":false},\"excerpt\":{\"rendered\":\"\",\"protected\":false},\"author\":8,\"featured_media\":3102,\"template\":\"\",\"event_categories\":[],\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v18.6 - https:\\/\\/yoast.com\\/wordpress\\/plugins\\/seo\\/ -->\\n<title>Kanab Spooktacular Trunk or Treat | Visit Southern Utah<\\