ge-height\":512,\"large\":\"\\/wp-content\\/uploads\\/2019\\/09\\/DSC_0637-1024x683.jpg\",\"large-width\":1024,\"large-height\":683,\"1536x1536\":\"\\/wp-content\\/uploads\\/2019\\/09\\/DSC_0637-1536x1024.jpg\",\"1536x1536-width\":1536,\"1536x1536-height\":1024,\"2048x2048\":\"\\/wp-content\\/uploads\\/2019\\/09\\/DSC_0637.jpg\",\"2048x2048-width\":1620,\"2048x2048-height\":1080}}],\"information_block_2\":\"\",\"related_events\":\"\",\"recurrance\":\"\",\"document_download\":false,\"end_date\":\"October 14, 2023 17:00:00\"},\"featured_image_url\":\"\\/wp-content\\/uploads\\/2019\\/09\\/Red-Rocktoberfest-sego-1024x682-768x512.jpg\",\"_links\":{\"self\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\\/1774\"}],\"collection\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\"}],\"about\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/types\\/events\"}],\"author\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/users\\/8\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media\\/3105\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media?parent=1774\"}],\"wp:term\":[{\"taxonomy\":\"event_categories\",\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/event_categories?post=1774\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}',1,'2023-10-05 04:52:01','2023-10-06 22:56:14'),(65,'Glendale Harvest Festival','vsu','1768',220,'The Annual Heritage Apple Festival\nGlendale has always been known for their wonderful apples. The Glendale Heritage Apple Festival was started to celebrate our Pioneer Heritage and the many talents that are in this small town. Through the years it has evolved and become a celebration not just for the people of Glendale but the many talented people of the community and tourists in surrounding areas.\nThe festival typically takes place in the fall, when the apples are at their peak of ripeness. The festival features a variety of apple-themed activities and attractions, including apple picking, apple tasting, and apple-themed food vendors. There are also craft vendors selling handmade goods, quilts on display, as well as live music and entertainment.\nIn addition to celebrating the apple harvest, the Glendale Heritage Apple Festival also aims to preserve and promote the town&#8217;s unique history and culture. The festival is a great opportunity for visitors to experience the small-town charm of Glendale and learn about the importance of apples to the local community.\n&nbsp;',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-10-10 08:00:00','2025-10-11 17:00:00','{\"id\":1768,\"date\":\"2019-09-29T19:25:19\",\"date_gmt\":\"2019-09-29T19:25:19\",\"guid\":{\"rendered\":\"http:\\/\\/kanecounty.fluidstaging.com\\/?post_type=events&#038;p=1768\"},\"modified\":\"2025-03-20T15:00:49\",\"modified_gmt\":\"2025-03-20T21:00:49\",\"slug\":\"glendale-apple-festival\",\"status\":\"publish\",\"type\":\"events\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/glendale-apple-festival\\/\",\"title\":{\"rendered\":\"Glendale Harvest Festival\"},\"content\":{\"rendered\":\"<p>Do you like a local festival with good food, lots of themed events and event regional history? Wait &#8217;til you taste the apple pies! Glendale Heritage &amp; Apple Festival celebrates the small southern Utah town of Glendale and their intriguing history, along with the best tasting apple pie in the county!<\\/p>\\n\",\"protected\":false},\"excerpt\":{\"rendered\":\"<p>Do you like a local festival with good food, lots of themed events and event regional history? Wait &#8217;til you &hellip;<\\/p>\\n\",\"protected\":false},\"author\":8,\"featured_media\":2974,\"template\":\"\",\"event_categories\":[],\"class_list\":[\"post-1768\",\"events\",\"type-events\",\"status-publish\",\"has-post-thumbnail\",\"hentry\"],\"acf\":{\"additional_heading\":\"\",\"location_name\":\"Glendale Utah\",\"address\":\"Glendale Town Park\",\"contact_number\":\"\",\"start_datetime\":\"October 10, 2025 8:00 am\",\"multi_day_event\":true,\"end_date\":\"October 11, 2025 17:00:00\",\"category\":{\"term_id\":15,\"name\":\"Regional Events\",\"slug\":\"regional-events\",\"term_group\":0,\"term_taxonomy_id\":15,\"taxonomy\":\"event_categories\",\"description\":\"#00E1FE\",\"parent\":0,\"count\":0,\"filter\":\"raw\"},\"redirect_url\":\"http:\\/\\/www.facebook.com\\/GlendaleAppleFestival\",\"information_block\":\"<p>The Annual Heritage Apple Festival<\\/p>\\n<p>Glendale has always been known for their wonderful apples. The Glendale Heritage Apple Festival was started to celebrate our Pioneer Heritage and the many talents that are in this small town. Through the years it has evolved and become a celebration not just for the people of Glendale but the many talented people of the community and tourists in surrounding areas.<\\/p>\\n<p>The festival typically takes place in the fall, when the apples are at their peak of ripeness. The festival features a variety of apple-themed activities and attractions, including apple picking, apple tasting, and apple-themed food vendors. There are also craft vendors selling handmade goods, quilts on display, as well as live music and entertainment.<\\/p>\\n<p>In addition to celebrating the apple harvest, the Glendale Heritage Apple Festival also aims to preserve and promote the town&#8217;s unique history and culture. The festival is a great opportunity for visitors to experience the small-town charm of Glendale and learn about the importance of apples to the local community.<\\/p>\\n<p>&nbsp;<\\/p>\\n<p><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"aligncenter wp-image-13139 size-full\\\" src=\\\"https:\\/\\/visitsouthernutah.com\\/wp-content\\/uploads\\/2019\\/09\\/295840081_101843599293591_6872364460571556938_n.jpg\\\" alt=\\\"\\\" width=\\\"2048\\\" height=\\\"2048\\\" srcset=\\\"\\/wp-content\\/uploads\\/2019\\/09\\/295840081_101843599293591_6872364460571556938_n.jpg 2048w, \\/wp-content\\/uploads\\/2019\\/09\\/295840081_101843599293591_6872364460571556938_n-300x300.jpg 300w, \\/wp-content\\/uploads\\/2019\\/09\\/295840081_101843599293591_6872364460571556938_n-1024x1024.jpg 1024w, \\/wp-content\\/uploads\\/2019\\/09\\/295840081_101843599293591_6872364460571556938_n-150x150.jpg 150w, \\/wp-content\\/uploads\\/2019\\/09\\/295840081_101843599293591_6872364460571556938_n-768x768.jpg 768w, \\/wp-content\\/uploads\\/2019\\/09\\/295840081_101843599293591_6872364460571556938_n-1536x1536.jpg 1536w\\\" sizes=\\\"(max-width: 2048px) 100vw, 2048px\\\" \\/><\\/p>\\n\",\"information_heading\":\"\",\"information_block_1\":\"\",\"gallery\":[{\"ID\":13135,\"id\":13135,\"title\":\"310992370_129332199883099_7358609264588317148_n-glendaleapplefestival\",\"filename\":\"310992370_129332199883099_7358609264588317148_n.jpg\",\"filesize\":332637,\"url\":\"\\/wp-content\\/uploads\\/2019\\/09\\/310992370_129332199883099_7358609264588317148_n.jpg\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/glendale-apple-festival\\/310992370_129332199883099_7358609264588317148_n\\/\",\"alt\":\"\",\"author\":\"8\",\"description\":\"\",\"caption\":\"\",\"name\":\"310992370_129332199883099_7358609264588317148_n\",\"status\":\"inherit\",\"uploaded_to\":1768,\"date\":\"2023-03-28 20:00:15\",\"modified\":\"2023-09-26 18:29:24\",\"menu_order\":0,\"mime_type\":\"image\\/jpeg\",\"type\":\"image\",\"subtype\":\"jpeg\",\"icon\":\"https:\\/\\/visitsouthernutah.com\\/wp-includes\\/images\\/media\\/default.png\",\"width\":1200,\"height\":1200,\"sizes\":{\"thumbnail\":\"\\/wp-content\\/uploads\\/2019\\/09\\/310992370_129332199883099_7358609264588317148_n-150x150.jpg\",\"thumbnail-width\":150,\"thumbnail-height\":150,\"medium\":\"\\/wp-content\\/uploads\\/2019\\/09\\/310992370_129332199883099_7358609264588317148_