L,NULL,'2025-03-13 00:00:00','2025-04-19 00:00:00','{\"categoryid\":\"1\",\"category\":\"Regular Event\",\"eventid\":\"108984\",\"date\":\"2025-03-21\",\"datestart\":\"2025-03-13\",\"dateend\":\"2025-04-19\",\"recurrencedatestart\":\"2025-03-13\",\"recurrencedateend\":\"2025-04-05\",\"latitude\":\"36.935746\",\"longitude\":\"-111.485594\",\"isrecurring\":\"true\",\"isallday\":\"false\",\"isregresrequired\":\"false\",\"isfree\":\"true\",\"regresurl\":\"\",\"regresinfo\":\"\",\"infourl\":\"\",\"feeinfo\":\"\",\"timeinfo\":\"Glen Canyon National Recreation Area follows Arizona time. Time is Mountain Standard Time all year. You will be very close to the Utah border, so make sure your clock is set to AZ time.\",\"title\":\"Dam Talk at Carl Hayden Visitor Center\",\"contactname\":\"\",\"contacttelephonenumber\":\"\",\"contactemailaddress\":\"\",\"description\":\"<p><span data-olk-copy-source=\\\"MessageBody\\\">Join a park ranger to learn avariety of subjects.<\\/span><\\/p>\",\"location\":\"Carl Hyden Visitor Center is on Hwy 89 at Glen Canyon Dam, just north of Page AZ.\",\"tags\":[\"Glen Canyon National Recreation Area\",\"Carl Hayden Visitor Center\",\"glen canyon dam\",\"Ranger Talk\",\"glca2025\"],\"types\":[\"Talk\"],\"recurrencerule\":\"DTSTART=20250313T070000Z;UNTIL=20250405T070000Z;FREQ=WEEKLY;WKST=SU;BYDAY=TH,FR,SA;COUNT=0;INTERVAL=1\",\"sitecode\":\"glca\",\"sitetype\":\"park\",\"datetimecreated\":\"2025-02-13T15:56:27.46\",\"datetimeupdated\":\"2025-03-19T09:20:52.03\",\"createuser\":\"escroggs@nps.gov\",\"updateuser\":\"escroggs@nps.gov\",\"risdpoiid\":\"e91e503c-a406-4a02-81fb-0bdf1562fa2d\",\"times\":[{\"timestart\":\"11:00 AM\",\"timeend\":\"11:30 AM\",\"sunrisestart\":\"false\",\"sunsetend\":\"false\"}],\"dates\":[\"2025-03-21\",\"2025-03-22\",\"2025-03-27\",\"2025-03-28\",\"2025-03-29\",\"2025-04-03\",\"2025-04-04\",\"2025-04-05\"],\"images\":[],\"imageidlist\":\"\",\"subjectname\":\"\",\"parkfullname\":\"Glen Canyon National Recreation Area\",\"portalname\":\"\",\"organizationname\":\"\",\"id\":\"0B052D35-A30B-43FF-33BE5D39D7BA2BF6\"}',1,'2025-03-21 18:08:53','2025-03-21 18:08:53'),(92,'Dam Overlook Hike','nps','A4C21207-CD80-C917-77828F81B456F05F',4,'Meet the ranger at the Dam Overlook for a guided hike along the Vermilion View trail. Learn more about the plants, animals, geology, and history of Glen Canyon.\\r\\n\\r\\nThe trailhead is at Dam Overlook, on Scenic View Rd behind the Dennys.',36.9243,-111.479,NULL,NULL,NULL,NULL,NULL,'2025-03-21 00:00:00','2025-03-21 00:00:00','{\"categoryid\":\"1\",\"category\":\"Regular Event\",\"eventid\":\"109689\",\"date\":\"2025-03-21\",\"datestart\":\"2025-03-21\",\"dateend\":\"2025-03-21\",\"recurrencedatestart\":\"2025-03-21\",\"recurrencedateend\":\"2025-04-19\",\"latitude\":\"36.924309\",\"longitude\":\"-111.478559\",\"isrecurring\":\"false\",\"isallday\":\"false\",\"isregresrequired\":\"false\",\"isfree\":\"true\",\"regresurl\":\"\",\"regresinfo\":\"\",\"infourl\":\"\",\"feeinfo\":\"\",\"timeinfo\":\"All times are Mountain Standard Time. Make sure your clock is set to AZ time.\",\"title\":\"Dam Overlook Hike\",\"contactname\":\"\",\"contacttelephonenumber\":\"\",\"contactemailaddress\":\"\",\"description\":\"<p>Meet the ranger at the Dam Overlook for a guided hike along the Vermilion View trail.\\u00a0Learn more about the plants, animals, geology, and history of Glen Canyon.<\\/p>\",\"location\":\"The trailhead is at Dam Overlook, on Scenic View Rd behind the Dennys.\",\"tags\":[\"Glen Canyon National Recreation Area\",\"dam overlook\",\"trailhead\",\"ranger led hikes\",\"glca2025\",\"Guided Hike\"],\"types\":[\"Hike\",\"Talk\",\"Walk\"],\"recurrencerule\":\"\",\"sitecode\":\"glca\",\"sitetype\":\"park\",\"datetimecreated\":\"2025-02-26T14:12:43.957\",\"datetimeupdated\":null,\"createuser\":\"escroggs@nps.gov\",\"updateuser\":\"\",\"risdpoiid\":\"a4901190-8673-4f52-94fa-429642c5a104\",\"times\":[{\"timestart\":\"05:30 PM\",\"timeend\":\"06:30 PM\",\"sunrisestart\":\"fal