\\/visitsouthernutah.com\\/search\\/{search_term_string}\"},\"query-input\":\"required name=search_term_string\"}],\"inLanguage\":\"en-US\"}]}},\"featured_image_url\":\"\\/wp-content\\/uploads\\/2022\\/06\\/ghdfghd-768x666.png\",\"_links\":{\"self\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\\/9908\"}],\"collection\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\"}],\"about\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/types\\/events\"}],\"author\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/users\\/8\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media\\/9914\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media?parent=9908\"}],\"wp:term\":[{\"taxonomy\":\"event_categories\",\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/event_categories?post=9908\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}',1,'2025-03-21 18:18:59','2025-03-21 18:18:59'),(115,'North Rim &#8211; Grand Canyon Start of Season','vsu','8669',200,'A worthwhile trip for those who enjoy the road less traveled, the North Rim, or &#8220;other side&#8221; of Grand Canyon is visited by only 10% of all Grand Canyon visitors.\n\nThe North Rim is over 8000 feet (2438 m.) in elevation\nThere is one lodge, Grand Canyon Lodge.\nand one campground, operated by the National Park Service\n\nReservations for Lodging and the North Rim Campground are highly recommended.\nThe lodge also provides food and beverage service.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-15 07:00:00',NULL,'{\"id\":8669,\"date\":\"2021-12-30T16:32:00\",\"date_gmt\":\"2021-12-30T16:32:00\",\"guid\":{\"rendered\":\"https:\\/\\/visitsouthernutah.com\\/?post_type=events&#038;p=8669\"},\"modified\":\"2025-03-13T13:50:03\",\"modified_gmt\":\"2025-03-13T19:50:03\",\"slug\":\"north-rim\",\"status\":\"publish\",\"type\":\"events\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/north-rim\\/\",\"title\":{\"rendered\":\"North Rim &#8211; Grand Canyon Start of Season\"},\"content\":{\"rendered\":\"\",\"protected\":false},\"excerpt\":{\"rendered\":\"\",\"protected\":false},\"author\":8,\"featured_media\":8810,\"template\":\"\",\"event_categories\":[],\"class_list\":[\"post-8669\",\"events\",\"type-events\",\"status-publish\",\"has-post-thumbnail\",\"hentry\"],\"acf\":{\"additional_heading\":\"The North Rim of the Grand Canyon is now open! See what the quieter side of the park has to offer!\",\"location_name\":\"Grand Canyon Lodge\",\"address\":\"Grand Canyon National Park, AZ\",\"contact_number\":\"\",\"start_datetime\":\"May 15, 2025 7:00 am\",\"multi_day_event\":false,\"recurrance\":\"\",\"category\":{\"term_id\":11,\"name\":\"Parks &amp; Outdoor\",\"slug\":\"parks-outdoor\",\"term_group\":0,\"term_taxonomy_id\":11,\"taxonomy\":\"event_categories\",\"description\":\"#00FE3B\",\"parent\":0,\"count\":0,\"filter\":\"raw\"},\"redirect_url\":\"https:\\/\\/www.nps.gov\\/grca\\/planyourvisit\\/north-rim.htm\",\"document_download\":false,\"information_block\":\"<p>A worthwhile trip for those who enjoy the road less traveled, the North Rim, or &#8220;other side&#8221; of Grand Canyon is visited by only 10% of all Grand Canyon visitors.<\\/p>\\n<ul>\\n<li>The\\u00a0<strong>North Rim<\\/strong>\\u00a0is over\\u00a0<strong>8000 feet (2438 m.)<\\/strong>\\u00a0<strong>in elevation<\\/strong><\\/li>\\n<li>There is\\u00a0<strong>one lodge<\\/strong>,\\u00a0<a id=\\\"https:\\/\\/www.grandcanyonforever.com\\/index.php\\/lodging\\/|\\\" href=\\\"https:\\/\\/www.grandcanyonforever.com\\/index.php\\/lodging\\/\\\" data-toggle=\\\"modal\\\" data-target=\\\"#myModal\\\" data-remote=\\\"\\/common\\/commonspot\\/customcf\\/modals\\/modal_intercept.cfm?targetURL=https%3A%2F%2Fwww.grandcanyonforever.com%2Findex.php%2Flodging%2F\\\">Grand Canyon Lodge<\\/a><strong>.<\\/strong><\\/li>\\n<li>and one\\u00a0<strong><span id=\\\"CP___PAGEID=1954290,cg-nr.htm,11006|\\\">campground,<\\/span><\\/strong>\\u00a0operated by the National Park Service<\\/li>\\n<\\/ul>\\n<p><strong>Reservations<\\/strong>\\u00a0for\\u00a0<a id=\\\"CP___PAGEID=6411720,lodging-nr.htm,11006|\\\" href=\\\"https:\\/\\/www.nps.gov\\/grca\\/planyourvisit\\/lodging-nr.htm\\\">Lodging<\\/a>\\u00a0and the\\u00a0<strong><a id=\\\"anch_21\\\" href=\\\"https:\\/\\/www.nps.gov\\/grca\\/planyourvisit\\/cg-nr.htm\\\">North Rim Campground<\\/a>\\u00a0<\\/strong>are highly recommended.<\\/p>\\n<p>The lodge also provides\\u00a0<a id=\\\"https:\\/\\/www.grandcanyonforever.com\\/dining|\\\" href=\\\"https:\\/\\/www.grandcanyonforever.com\\/dining\\\" data-toggle=\\\"modal\\\" data-target=\\\"#myModal\\\" data-remote=\\\"\\/common\\/commonspot\\/customcf\\/modals\\/modal_intercept.cfm?targetURL=https%3A%2F%2Fwww.grandcanyonforever.com%2Fdining\\\">food and beverage service<\\/a>.<\\/p>\\n\",\"information_heading\":\"\",\"information_block_1\":\"\",\"gallery\":false,\"information_block_2\":\"\",\"related_events\":\"\"},\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v23.1 - https:\\/\\/yoast.com\\/wordpress\\/plugins\\/seo\\/ -->\\n<title>North Rim - Grand Canyon Start of Season | Visit Southern Utah<\\/title>\\n<meta name=\\\"description\\\" content=\\\"A worthwhile trip for those who enjoy the road less traveled, the North Rim, or \\u201cother side\\u201d of Grand Canyon is visited by only 10% of all Grand Canyon visitors.\\\" \\/>\\n<meta name=\\\"robots\\\" content=\\\"index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/visitsouthernutah.com\\/events\\/north-rim\\/\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta property=\\\"og:type\\\" content=\\\"article\\\" \\/>\\n<meta prop