\/v2\\/events\\/4564\"}],\"collection\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/events\"}],\"about\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/types\\/events\"}],\"author\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/users\\/8\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media\\/4570\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media?parent=4564\"}],\"wp:term\":[{\"taxonomy\":\"event_categories\",\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/event_categories?post=4564\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}',1,'2025-03-21 18:18:59','2025-03-21 18:18:59'),(120,'Kanab&#8217;s Independence Day Celebration','vsu','3714',229,'Join us for the best small town Independence Day celebration in the country! Celebrate Independence Day, The Kanab Way!\nEven visitors feel at home and full of patriotism when they celebrate the 4th of July in Southern Utah! Listen bright and early at 6:00 AM for the cannons as they Blast Off!, awakening the whole town for the days festivities. Soon after, join in on a Color Fun Run 5K starting at the church in the center of town at 7:00AM.\nThen, at 10 AM join the town on Center Street for a parade you’ll have the chance to see twice, as the parade turns around at the end of the street, only to end just where it began!\nAfter the parade, find yourself at Jacob Hamblin Park for vendors, entertainment, and many more festivities throughout the day and into the evening. Once the sun sets and the entertainment wraps up, prepare yourself for one of the most unique firework shows you have ever seen! Fireworks shoot off overhead at Jacob Hamblin park, illuminating the red cliffs while sending echoes all throughout the town.\nCelebrate Independence day in small town USA and we’re sure you’ll return again, and again! Will you join us in celebrating Independence Day?\nWatch the livestream of the parade here, utahlivestream.com/live',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-07-04 06:00:00',NULL,'{\"id\":3714,\"date\":\"2020-03-05T22:00:19\",\"date_gmt\":\"2020-03-05T22:00:19\",\"guid\":{\"rendered\":\"https:\\/\\/visitsouthernutah.com\\/?post_type=events&#038;p=3714\"},\"modified\":\"2025-03-13T15:38:38\",\"modified_gmt\":\"2025-03-13T21:38:38\",\"slug\":\"kanabs-independence-day-celebration\",\"status\":\"publish\",\"type\":\"events\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/kanabs-independence-day-celebration\\/\",\"title\":{\"rendered\":\"Kanab&#8217;s Independence Day Celebration\"},\"content\":{\"rendered\":\"\",\"protected\":false},\"excerpt\":{\"rendered\":\"\",\"protected\":false},\"author\":8,\"featured_media\":2639,\"template\":\"\",\"event_categories\":[],\"class_list\":[\"post-3714\",\"events\",\"type-events\",\"status-publish\",\"has-post-thumbnail\",\"hentry\"],\"acf\":{\"additional_heading\":\"\",\"location_name\":\"Downtown Kanab\",\"address\":\"\",\"contact_number\":\"435-644-3696\",\"start_datetime\":\"July 4, 2025 6:00 am\",\"multi_day_event\":false,\"recurrance\":\"\",\"category\":{\"term_id\":18,\"name\":\"Live Music &amp; Entertainment\",\"slug\":\"live-music-entertainment\",\"term_group\":0,\"term_taxonomy_id\":18,\"taxonomy\":\"event_categories\",\"description\":\"#FE0000\",\"parent\":0,\"count\":0,\"filter\":\"raw\"},\"redirect_url\":\"https:\\/\\/visitsouthernutah.com\\/kanab-fourth\\/\",\"document_download\":false,\"information_block\":\"<p>Join us for the best small town Independence Day celebration in the country! Celebrate Independence Day, The Kanab Way!<\\/p>\\n<p>Even visitors feel at home and full of patriotism when they celebrate the 4th of July in Southern Utah! Listen bright and early at 6:00 AM for the cannons as they Blast Off!, awakening the whole town for the days festivities.\\u00a0Soon after, join in on a Color Fun Run 5K starting at the church in the center of town at 7:00AM.<\\/p>\\n<p>Then, at 10 AM join the town on Center Street for a parade you\\u2019ll have the chance to see twice, as the parade turns around at the end of the street, only to end just where it began!<\\/p>\\n<p><img decoding=\\\"async\\\" src=\\\"https:\\/\\/www.visitsouthernutah.com\\/media\\/uploads\\/images\\/DSC_1694.JPG\\\" alt=\\\"\\\" \\/>After the parade, find yourself at Jacob Hamblin Park for vendors, entertainment, and many more festivities throughout the day and into the evening. Once the sun sets and the entertainment wraps up, prepare yourself for one of the most unique firework shows you have ever seen! Fireworks shoot off overhead at Jacob Hamblin park, illuminating the red cliffs while sending echoes all throughout the town.<\\/p>\\n<p>Celebrate Independence day in small town USA and we\\u2019re sure you\\u2019ll return again, and again! Will you join us in celebrating Independence Day?<\\/p>\\n<p>Watch the livestream of the parade here, <a href=\\\"http:\\/\\/utahlivestream.com\\/live\\\">utahlivestream.com\\/live<\\/a><\\/p>\\n\",\"information_heading\":\"\",\"information_block_1\":\"\",\"gallery\":[{\"ID\":3058,\"id\":3058,\"title\":\"201907041257-1024x683-4thparade\",\"filename\":\"201907041257-1024x683.jpg\",\"filesize\":198325,\"url\":\"\\/wp-content\\/uploads\\/2019\\/12\\/201907041257-1024x683.jpg\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/kanab-fourth\\/201907041257-1024x683-4thparade\\/\",\"alt\":\"\",\"author\":\"8\",\"description\":\"\",\"caption\":\"\",\"name\":\"201907041257-1024x683-4thparade\",\"status\":\"inherit\",\"uploaded_to\":1843,\"date\":\"2019-12-04 21:19:33\",\"modified\":\"2023-09-18 15:13:38\",\"menu_order\":0,\"mime_type\":\"image\\/jpeg\",\"type\":\"image\",\"subtype\":\"jpeg\",\"icon\":\"https:\\/\\/visitsouthernutah.com\\/wp-includes\\/images\\/media\\/default.png\",\"width\":1024,\"height