/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/types\\/events\"}],\"author\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/users\\/8\"}],\"wp:featuredmedia\":[{\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media\\/2639\"}],\"wp:attachment\":[{\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/media?parent=3714\"}],\"wp:term\":[{\"taxonomy\":\"event_categories\",\"embeddable\":true,\"href\":\"https:\\/\\/visitsouthernutah.com\\/wp-json\\/wp\\/v2\\/event_categories?post=3714\"}],\"curies\":[{\"name\":\"wp\",\"href\":\"https:\\/\\/api.w.org\\/{rel}\",\"templated\":true}]}}',1,'2025-03-21 18:18:59','2025-03-21 18:25:01'),(121,'Kanab 10K','vsu','3674',206,'The Kanab 10K is one of the most beautiful runs in the world! All participants will receive a swag bag and race shirt! Winners will receive one-of-a-kind trophies! Don&#8217;t miss this opportunity for an incredible run through Southern Utah&#8217;s best kept secret.\nThe person with the oldest shirt will receive a custom trophy!\nStrollers are welcome on the course!\nSAME LOCATION AS LAST YEAR!! All participants will need to be at the Kanab Center(20 N 100 E) between 6:00-6:45 am to catch a bus to the starting line. Last ride leaves at 6:45! No exceptions! The race MUST begin at 7:00 am.\nOnline registration closes on May 10th @ 5PM. Packet pick up will be at the Kanab City Office. PLEASE pre-register for best pricing and to be sure you get the shirt size you want. There will be no registration on the morning of the race!\n&nbsp;',NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2025-05-10 07:00:00',NULL,'{\"id\":3674,\"date\":\"2020-02-26T20:58:49\",\"date_gmt\":\"2020-02-26T20:58:49\",\"guid\":{\"rendered\":\"https:\\/\\/visitsouthernutah.com\\/?post_type=events&#038;p=3674\"},\"modified\":\"2025-03-13T11:21:08\",\"modified_gmt\":\"2025-03-13T17:21:08\",\"slug\":\"kanab-10k\",\"status\":\"publish\",\"type\":\"events\",\"link\":\"https:\\/\\/visitsouthernutah.com\\/events\\/kanab-10k\\/\",\"title\":{\"rendered\":\"Kanab 10K\"},\"content\":{\"rendered\":\"\",\"protected\":false},\"excerpt\":{\"rendered\":\"\",\"protected\":false},\"author\":8,\"featured_media\":17701,\"template\":\"\",\"event_categories\":[],\"class_list\":[\"post-3674\",\"events\",\"type-events\",\"status-publish\",\"has-post-thumbnail\",\"hentry\"],\"acf\":{\"additional_heading\":\"\",\"location_name\":\"Kanab Center\",\"address\":\"20 N 100 E, Kanab, UT 84741\",\"contact_number\":\"435-644-2534\",\"start_datetime\":\"May 10, 2025 7:00 am\",\"multi_day_event\":false,\"recurrance\":\"\",\"category\":{\"term_id\":12,\"name\":\"Sports &amp; Recreation\",\"slug\":\"sports-recreation\",\"term_group\":0,\"term_taxonomy_id\":12,\"taxonomy\":\"event_categories\",\"description\":\"#FE00F4\",\"parent\":0,\"count\":0,\"filter\":\"raw\"},\"redirect_url\":\"https:\\/\\/runnercard.com\\/roadrace\\/public\\/raceGroup\\/977347\",\"document_download\":false,\"information_block\":\"<p>The Kanab 10K is one of the most beautiful runs in the world! All participants will receive a swag bag and race shirt! Winners will receive one-of-a-kind trophies! Don&#8217;t miss this opportunity for an incredible run through Southern Utah&#8217;s best kept secret.<\\/p>\\n<p>The person with the oldest shirt will receive a custom trophy!<\\/p>\\n<p>Strollers are welcome on the course!<\\/p>\\n<p>SAME LOCATION AS LAST YEAR!! All participants will need to be at the Kanab Center(20 N 100 E) between 6:00-6:45 am to catch a bus to the starting line. Last ride leaves at 6:45! No exceptions! The race MUST begin at 7:00 am.<\\/p>\\n<p>Online registration closes on May 10th @ 5PM. Packet pick up will be at the Kanab City Office. PLEASE pre-register for best pricing and to be sure you get the shirt size you want. There will be no registration on the morning of the race!<\\/p>\\n<p>&nbsp;<\\/p>\\n<p><img loading=\\\"lazy\\\" decoding=\\\"async\\\" class=\\\"alignnone wp-image-21086 size-full\\\" src=\\\"https:\\/\\/visitsouthernutah.com\\/wp-content\\/uploads\\/2020\\/02\\/482320701_931803435782490_7744457507081981080_n.jpg\\\" alt=\\\"\\\" width=\\\"940\\\" height=\\\"788\\\" srcset=\\\"\\/wp-content\\/uploads\\/2020\\/02\\/482320701_931803435782490_7744457507081981080_n.jpg 940w, \\/wp-content\\/uploads\\/2020\\/02\\/482320701_931803435782490_7744457507081981080_n-300x251.jpg 300w, \\/wp-content\\/uploads\\/2020\\/02\\/482320701_931803435782490_7744457507081981080_n-768x644.jpg 768w\\\" sizes=\\\"(max-width: 940px) 100vw, 940px\\\" \\/><\\/p>\\n\",\"information_heading\":\"\",\"information_block_1\":\"\",\"gallery\":false,\"information_block_2\":\"\",\"related_events\":[{\"ID\":3667,\"post_author\":\"8\",\"post_date\":\"2020-02-25 22:55:28\",\"post_date_gmt\":\"2020-02-25 22:55:28\",\"post_content\":\"\",\"post_title\":\"Jacob Hamblin Days\",\"post_excerpt\":\"\",\"post_status\":\"publish\",\"comment_status\":\"closed\",\"ping_status\":\"closed\",\"post_password\":\"\",\"post_name\":\"jacob-hamblin-days\",\"to_ping\":\"\",\"pinged\":\"\",\"post_modified\":\"2025-03-13 15:20:01\",\"post_modified_gmt\":\"2025-03-13 21:20:01\",\"post_content_filtered\":\"\",\"post_parent\":0,\"guid\":\"https:\\/\\/visitsouthernutah.com\\/?post_type=events&#038;p=3667\",\"menu_order\":0,\"post_type\":\"events\",\"post_mime_type\":\"\",\"comment_count\":\"0\",\"filter\":\"raw\"}]},\"yoast_head\":\"<!-- This site is optimized with the Yoast SEO plugin v23.1 - https:\\/\\/yoast.com\\/wordpress\\/plugins\\/seo\\/ -->\\n<title>Kanab 10K | Visit Southern Utah<\\/title>\\n<meta name=\\\"description\\\" content=\\\"Visit Southern Utah Kanab 10K\\\" \\/>\\n<meta name=\\\"robots\\\" content=\\\"index, follow, max-snippet:-1, max-image-preview:large, max-video-preview:-1\\\" \\/>\\n<link rel=\\\"canonical\\\" href=\\\"https:\\/\\/visitsouthernutah.com\\/events\\/kanab-10k\\/\\\" \\/>\\n<meta property=\\\"og:locale\\\" content=\\\"en_US\\\" \\/>\\n<meta propert